81	// This package's tsconfig (@tsconfig/node20, lib: es2023, no DOM) hits an @types/node quirk where
82	// the ambient `fetch`/`Response` types resolve to an empty structural type rather than undici's
83	// real one (its conditional type meant to defer to DOM lib's Response misfires with no DOM lib
84	// present either). Rather than cast at every call site, wrap `fetch` once with the shape we
85	// actually use.
86	interface HttpResponse {
87	  readonly ok: boolean;
88	  readonly status: number;
89	  text(): Promise<string>;
90	  json(): Promise<unknown>;
91	}
92	
93	async function httpFetch(input: string, init?: RequestInit): Promise<HttpResponse> {
94	  return (await fetch(input, init)) as unknown as HttpResponse;
95	}
