97	async function waitForReachable(baseUrl: string, timeoutMs = 180_000): Promise<void> {
98	  const start = Date.now();
99	  let lastError: unknown;
100	  while (Date.now() - start < timeoutMs) {
101	    try {
102	      const res = await httpFetch(`${baseUrl}/server/ping`);
103	      if (res.ok) return;
104	    } catch (error) {
105	      lastError = error;
106	    }
107	    await new Promise((resolve) => setTimeout(resolve, 5_000));
108	  }
109	  throw new Error(
110	    `Directus at ${baseUrl} did not become reachable within ${timeoutMs}ms (VM boot/DNS/TLS may still be in ` +
111	      `progress — re-run \`pulumi up\` once it's up). Last error: ${String(lastError)}`,
112	  );
113	}
114	
115	async function login(baseUrl: string, email: string, password: string): Promise<string> {
116	  const res = await httpFetch(`${baseUrl}/auth/login`, {
117	    method: "POST",
118	    headers: { "Content-Type": "application/json" },
119	    body: JSON.stringify({ email, password }),
120	  });
121	  if (!res.ok) {
122	    throw new Error(`Directus login as ${email} failed: ${res.status} ${await res.text()}`);
123	  }
124	  return ((await res.json()) as { data: { access_token: string } }).data.access_token;
125	}
126	
127	async function directusRequest<T>(
128	  baseUrl: string,
129	  token: string,
130	  method: string,
131	  path: string,
132	  body?: unknown,
133	): Promise<T> {
134	  const res = await httpFetch(`${baseUrl}${path}`, {
135	    method,
136	    headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
137	    body: body !== undefined ? JSON.stringify(body) : undefined,
138	  });
139	  if (!res.ok) {
140	    throw new Error(`${method} ${path} -> ${res.status}: ${await res.text()}`);
141	  }
142	  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
143	}
