176	async function applySchema(baseUrl: string, token: string, schema: unknown): Promise<void> {
177	  const diff = await directusRequest<{ data: { hash: string; diff: unknown } | null }>(
178	    baseUrl,
179	    token,
180	    "POST",
181	    "/schema/diff",
182	    schema,
183	  );
184	  if (!diff.data) return; // null = already in sync, nothing to apply
185	  await directusRequest(baseUrl, token, "POST", "/schema/apply", diff.data);
